import csv

# Read catalog
catalog = {}
with open(CATALOG_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        catalog[row['timeseries_id']] = row

# Find air temperature sensor series
at_sensor_ids = {}
for tid, row in catalog.items():
    if row['point_class'] == 'Zone_Air_Temperature_Sensor':
        # extract zone name
        uri = row['point_uri']
        name = uri.split('#')[-1]
        zone = name.split('.')[0]
        at_sensor_ids[tid] = zone

print("Air temp sensors:", at_sensor_ids)

# Read values
import os
print("Values file exists:", os.path.exists(VALUES_CSV))

target_ts = "2018-04-20T15:00:00"
results = {}
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        if row['timeseries_id'] in at_sensor_ids and row['timestamp'] == target_ts:
            results[row['timeseries_id']] = float(row['value'])

print("Values at", target_ts, ":", results)
for tid, val in results.items():
    print(at_sensor_ids[tid], val)
